// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // deployer is the initial owner; make the deployer renounce to let fuzzer become owner
        vm.prank(address(this));
        c.renounceOwnership();
        // Ensure the contract is in initial state after renounce
        require(c.owner() == address(0), "setup failed");

        // Now let the fuzzer-provided address become the owner
        vm.prank(newOwner);
        c.initialize();
        require(c.owner() == newOwner, "init failed");

        // Choose a different address to transfer ownership to
        address targetOwner = address(uint160(uint256(keccak256(abi.encode(newOwner)))));
        vm.assume(targetOwner != address(0));
        vm.assume(targetOwner != newOwner);

        vm.prank(newOwner);
        c.transferOwnership(targetOwner);

        assertTrue(c.owner() == targetOwner);
    }
}

