pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address operator, address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(operator != address(0));
        vm.assume(caller != address(0));
        vm.assume(operator != caller);
        // Initialize the contract and set the operator as a program operator to allow calling transferOwnership
        c.initialize();
        vm.prank(operator);
        c.transferOwnership(operator);
        vm.prank(operator);
        c.programOperators(caller); // For future steps if needed; not strictly required for transferOwnership but harmless
        // Ensure that the caller is authorized to transfer ownership (must be the current owner)
        vm.prank(operator);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner, "owner should be newOwner");
    }
}

