pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedOwner) public {
        // The deciding value is any non-zero address that triggers a top-level init.
        vm.assume(fuzzedOwner != address(0));
        // initialize() is public external and expects no parameters, but we call it via the contract.
        // The reference always successfully initializes, the buggy one silently fails to update _initialized.
        c.initialize();
        // Read the actual version via the public getter exposed by Initializable.
        uint8 version = c._getInitializedVersion();
        assertTrue(version == 1);
    }
}

