pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint8 callCount) public {
        vm.assume(callCount >= 1 && callCount <= 5);
        vm.assume(actor != address(0));
        vm.startPrank(actor);
        c.initialize();
        for (uint8 i = 1; i < callCount; i++) {
            c.initialize();
        }
        vm.stopPrank();
        // _getInitializedVersion must return 1, ensuring only one initialization counted
        assertTrue(c._getInitializedVersion() == 1);
    }
}

